export const CreateConversationBody = zod.object({
  "participantId": zod.number()
})

export const CreateConversationResponse = zod.object({
  "id": zod.number(),
  "participantId": zod.number(),
  "participantUsername": zod.string(),
  "participantAvatarUrl": zod.string().nullish(),
  "lastMessage": zod.string().nullish(),
  "lastMessageAt": zod.string().nullish(),
  "unreadCount": zod.number().optional(),
  "createdAt": zod.string()
})


/**
 * @summary Get messages in a conversation
 */
export const ListMessagesParams = zod.object({
  "id": zod.coerce.number()
})

export const ListMessagesResponseItem = zod.object({
  "id": zod.number(),
  "conversationId": zod.number(),
  "senderId": zod.number(),
  "senderUsername": zod.string().optional(),
  "content": zod.string(),
  "createdAt": zod.string()
})
export const ListMessagesResponse = zod.array(ListMessagesResponseItem)


/**
 * @summary Send a message in a conversation
 */
export const SendMessageParams = zod.object({
  "id": zod.coerce.number()
})

export const SendMessageBody = zod.object({
  "content": zod.string()
})

export const SendMessageResponse = zod.object({
  "id": zod.number(),
  "conversationId": zod.number(),
  "senderId": zod.number(),
  "senderUsername": zod.string().optional(),
  "content": zod.string(),
  "createdAt": zod.string()
})


/**
 * @summary Top bettors by win rate and profit
 */
export const getLeaderboardResponseStreakMin = 7;
export const getLeaderboardResponseStreakMax = 7;



export const GetLeaderboardResponseItem = zod.object({
  "userId": zod.number(),
  "username": zod.string(),
  "avatarUrl": zod.string().nullish(),
  "totalBets": zod.number(),
  "wins": zod.number(),
  "winRate": zod.number(),
  "totalProfit": zod.number(),
  "roi": zod.number(),
  "streak": zod.array(zod.object({
  "date": zod.string(),
  "profit": zod.number(),
  "profitable": zod.boolean()
})).min(getLeaderboardResponseStreakMin).max(getLeaderboardResponseStreakMax),
  "rank": zod.number()
})
export const GetLeaderboardResponse = zod.array(GetLeaderboardResponseItem)


